export class ComputeKernel {
    constructor(
        resources: Record<string, ShaderResource>,
        wgslCode: string,
        workgroupSize: [number, number, number] = [64, 1, 1]
    );

    // Swap buffers without recompiling shader pipelines:
    public setResource(name: string, resource: ShaderResource): void;

    // Dispatches workgroups and returns a cached ComputeCommand:
    public dispatch(device: GPUDevice, dispatchX: number, dispatchY: number = 1, dispatchZ: number = 1): ComputeCommand;
}

export class ComputeUpdate extends Pass {
    public setup(builder: GraphBuilder) {
        builder.markUnculled(); // Guaranteed execution before raster passes
    }

    public execute(context: RenderContext) {
        const queue = context.sceneData.compute_queue;
        if (queue.length === 0) return;

        const pass = context.commandEncoder.beginComputePass();
        let lastPipeline: GPUComputePipeline | null = null;
        let lastBindGroup: GPUBindGroup | null = null;

        for (const command of queue) {
            if (command.pipeline !== lastPipeline) {
                pass.setPipeline(command.pipeline);
                lastPipeline = command.pipeline;
            }
            if (command.bind_group !== lastBindGroup) {
                pass.setBindGroup(0, command.bind_group);
                lastBindGroup = command.bind_group;
            }
            const d = command.dispatch_count;
            if (Array.isArray(d)) pass.dispatchWorkgroups(d[0], d[1], d[2]);
            else pass.dispatchWorkgroups(d);
        }
        pass.end();
    }
}

import { Scene, Circle, Instanced, ComputeKernel, Res, createBuffer, Color } from "retiam";

export class ParticleGalaxyScene extends Scene {
    public async run() {
        const COUNT = 100000; // 100k instances!
        this.camera.position.set([0, 40, 180]);

        // 1. Create Instanced Circle template
        const baseCircle = new Circle(0.3, { fill: Color.WHITE });
        const swarm = new Instanced(baseCircle, COUNT);
        this.add(swarm);

        // Prepare geometry and retrieve instance GPU storage buffer (Stride = 12 floats)
        swarm.geo.prepare(this);
        const instanceBuffer = swarm.getInstanceGPUBuffer();

        // 2. Uniform Buffer for time and simulation parameters
        const uniformBuffer = createBuffer(this.device, GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST, 16);

        // 3. Declare the WebGPU Compute Kernel
        const kernel = new ComputeKernel({
            "instances": Res.buffer("array<vec4f>", instanceBuffer, "read_write"),
            "params": Res.uniform("vec4f", uniformBuffer)
        }, `
            let idx = global_id.x;
            if (idx >= ${COUNT}u) { return; }

            let time = params.x;
            let fIdx = f32(idx);

            // Double Helix Vortex Dynamics
            let arm = fIdx % 4.0;
            let armAngle = arm * 1.5707963;
            let radius = 12.0 + (fIdx / ${COUNT}.0) * 85.0;
            let speed = (100.0 / radius) * 0.4;
            let angle = armAngle + (fIdx * 0.002) + time * speed;

            let px = cos(angle) * radius;
            let py = sin(time * 2.0 + radius * 0.1) * 6.0 + (sin(fIdx) * 4.0);
            let pz = sin(angle) * radius;
            let scale = 0.25 + 0.15 * sin(time * 3.0 + fIdx);

            // 1. Write Position (xyz) and Scale (w)
            instances[idx * 3u + 0u] = vec4f(px, py, pz, scale);

            // 2. Write Color (rgba) - Bioluminescent Rainbow
            let hue = (fIdx / ${COUNT}.0 + time * 0.05) % 1.0;
            let r = sin(hue * 6.28318) * 0.5 + 0.5;
            let g = sin((hue + 0.33) * 6.28318) * 0.5 + 0.5;
            let b = sin((hue + 0.66) * 6.28318) * 0.5 + 0.5;
            instances[idx * 3u + 1u] = vec4f(r, g, b, 0.85);

            // 3. Write 3D Rotation Quaternion (Identity)
            instances[idx * 3u + 2u] = vec4f(0.0, 0.0, 0.0, 1.0);
        `, [64, 1, 1]);

        const uniformData = new Float32Array(4);
        const workgroups = Math.ceil(COUNT / 64);

        // 4. Dispatch Compute in Frame Loop
        this.always(() => {
            uniformData[0] = this.time * 0.001; // Current elapsed time
            this.device.queue.writeBuffer(uniformBuffer, 0, uniformData);

            // Queue the compute dispatch for execution in ComputeUpdate pass:
            const cmd = kernel.dispatch(this.device, workgroups);
            this.addCompute(cmd);

            this.invalidate();
        });
    }
}

import { ComputeKernel, Res } from "retiam";

export function createProceduralNoiseGenerator(device: GPUDevice, targetView: GPUTextureView, width: number, height: number): ComputeKernel {
    return new ComputeKernel({
        "outputTex": Res.storageTexture(targetView, "rgba8unorm", "write")
    }, `
        let coord = vec2i(global_id.xy);
        if (coord.x >= ${width} || coord.y >= ${height}) { return; }

        let uv = vec2f(coord) / vec2f(${width}.0, ${height}.0);
        let n = fract(sin(dot(uv, vec2f(12.9898, 78.233))) * 43758.5453);

        textureStore(outputTex, coord, vec4f(n, n, n, 1.0));
    `, [16, 16, 1]);
}
